def profit(send, y, gain=400, cost=200):
    tp = (send & (y == 1)).sum()
    fp = (send & (y == 0)).sum()
    return int(gain * tp - cost * fp)

def month_report(p, threshold=0.3):
    return {
        "leads": len(p),
        "mean_pred": round(float(p.mean()), 3),
        "above": round(float((p > threshold).mean()), 3),
    }

import numpy as np
import pandas as pd
def profit_curve(p, y, value=1600, cost=150):
    rows = []
    for t in np.arange(0.02, 0.41, 0.02).round(2):
        send = p > t
        tp = int((send & (y == 1)).sum())
        rows.append({"threshold": t, "sent": int(send.sum()), "buyers": tp, "profit": value * tp - cost * int(send.sum())})
    return pd.DataFrame(rows)
